1	import { useCallback, useEffect, useRef, useState } from "react";
2	import { Button } from "@/presentation/components/ui/button";
3	import {
4		checkConversationUnlock,
5		MIN_GRAMMAR_POINTS,
6		MIN_VOCAB_COUNT,
7	} from "../../domain/conversation/services/ConversationUnlockService";
8	import type {
9		ConversationJudgeResult,
10		ConversationVerdict,
11	} from "../../domain/conversation/types";
12	import type { VocabularyService } from "../../domain/vocabulary/services/VocabularyLessonService";
13	import { useApp } from "../hooks/useApp";
14	import { useMicRecorder } from "../hooks/useMicRecorder";
15	
16	/**
17	 * How each verdict reads. `"unscored"` is deliberately neither of the other
18	 * two: it is the backend admitting it could not judge the turn, so showing
19	 * it as a fail would blame the learner for a system fault, and showing it as
20	 * a pass would be a lie.
21	 */
22	const VERDICT_PRESENTATION: Record<
23		ConversationVerdict,
24		{ label: string; note: string; color: string }
25	> = {
26		pass: {
27			label: "Good answer",
28			note: "That works as a reply.",
29			color: "var(--color-success, #15803d)",
30		},
31		fail: {
32			label: "Not quite",
33			note: "That does not answer the question yet — try again.",
34			color: "var(--color-danger, #b91c1c)",
35		},
36		unscored: {
37			label: "Could not be scored",
38			note: "Something went wrong on the backend, so this turn was not judged. It does not count against you.",
39			color: "var(--color-text-muted, #6b7280)",
40		},
41	};
42	
43	const BACKEND_UNAVAILABLE_MESSAGE =
44		"The conversation backend is not running, so there is nothing to talk to yet. Start it locally and reload this page.";
45	
46	/**
47	 * The learner's known-word snapshot sent with the opening request — never a
48	 * placeholder, and a real empty array (not an omitted field) when nothing is
49	 * learned yet. Extracted so this mapping stays unit-testable independent of
50	 * the unlock gate, which makes the zero-known-words case unreachable through
51	 * a real render once a learner is actually below `MIN_VOCAB_COUNT` (a
52	 * positive count is required to unlock the page in the first place).
53	 */
54	export function knownWordsFor(
55		vocab: Pick<VocabularyService, "getLearnedEntries">,
56	): string[] {
57		return vocab.getLearnedEntries().map((entry) => entry.thai);
58	}
59	
60	interface SessionQuestion {
61		sessionId: string;
62		questionText: string;
63		questionAudioUrl: string;
64	}
65	
66	/** Pass/fail/unscored, kept as three separate counts (never collapsed). */
67	interface Tally {
68		passed: number;
69		failed: number;
70		unscored: number;
71	}
72	
73	const EMPTY_TALLY: Tally = { passed: 0, failed: 0, unscored: 0 };
74	
75	function tallyTotal(tally: Tally): number {
76		return tally.passed + tally.failed + tally.unscored;
77	}
78	
79	function tallyAfter(tally: Tally, verdict: ConversationVerdict): Tally {
80		return {
81			passed: tally.passed + (verdict === "pass" ? 1 : 0),
82			failed: tally.failed + (verdict === "fail" ? 1 : 0),
83			unscored: tally.unscored + (verdict === "unscored" ? 1 : 0),
84		};
