	checkConversationUnlock,
	MIN_GRAMMAR_POINTS,
	MIN_VOCAB_COUNT,
} from "../../domain/conversation/services/ConversationUnlockService";
import type {
	ConversationJudgeResult,
	ConversationVerdict,
} from "../../domain/conversation/types";
