		if (!activeQuestion) return;
		if (audioRef.current) {
			audioRef.current.pause();
			audioRef.current.currentTime = 0;
		}
		const audio = new Audio(activeQuestion.questionAudioUrl);
		audioRef.current = audio;
		audio.play().catch(() => {});
	}, [activeQuestion]);

